                            // for loop
  for (var float v_i:=1.0; v_i<7.9; v_i:= v_i*1.35) { … } // Index variable v_i is declared and
                               // initialized in the for loop header. Variable 
                               // v_i only is visible in the loop body.

// Iterate over hexstring
  //
  var hexstring t := '12D'H;
  for (var hexstring e in t) {
     log(e);
  }
  // Output:
  //  '1'H
  //  '2'H
  //  'D'H

// Iterate over octetstring
  //
  var octetstring t := '12DE'O;
  for (var octetstring e in t) {
     log(e);
  }
  // Output:
  //  '12'O
  //  'DE'O

// Iterate over the keys of a map
  //
  var map from charstring to integer m := {
     ["a"] := 1,
     ["b"] := 2,
     ["c"] := 3,
  }
  for (var charstring k in m.from) {
     log(k, "=", m[k]);
  }
  // Output (order may vary):
  //  a=1
  //  b=2
  //  c=3

// Iterate over partially initialized value
  //
  var integer i := 0;
  var charstring e;
  for (e in {"a", -, "c"}) {
     log(i, ", ", e);
     i++;
  }
  log(i, ", ", e);
  // Output:
  //  0, "a"
  //  1, UNINITIALIZED
  //  2, "c"
  //  3, "c"

// Scope of iterator variable
  for (var integer x in {1,2,x}) { // ERROR: scope of x is limited to statement block
    // ...
  }

for (var charstring c in f()) { // Range expression is evaluated only once
    log(c);
  }
  // ...
  function f() return record of charstring {
    log("f called");
    return {"a", "b", "c"};
  }
  // Output:
  // f called
  // a
  // b
  // c

// Modify record of from inside a loop
  //
  var integer i := 0;
  var record of integer a := {1, 2, 3}
  for (var integer x in a) { // a is evaluated once, modification of `a` has no effect
                // on the number of iterations or iterated values.
     log(x);
     a[i+1] := 10*x;
     i++;
  }
  log(a);
  // Output:
  // 1
  // 2
  // 3
  // {1, 10, 20, 30}

